<?php
declare(strict_types=1); require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/auth.php';
if (!empty($_SESSION['cliente_id'])) { header('Location: cliente/index.php'); exit; } $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $n=trim((string)($_POST['nombre']??'')); $em=strtolower(trim((string)($_POST['email']??''))); $tel=trim((string)($_POST['telefono']??'')); $pw=(string)($_POST['password']??'');
 if ($n==='' || !filter_var($em,FILTER_VALIDATE_EMAIL) || strlen($pw)<10) $error='Verifica el nombre, el correo y usa una contraseña de mínimo 10 caracteres.';
 else { try { $q=$pdo->prepare('INSERT INTO clientes (nombre,email,telefono,password_hash) VALUES (:n,:e,:t,:p)'); $q->execute([':n'=>$n,':e'=>$em,':t'=>$tel?:null,':p'=>password_hash($pw,PASSWORD_DEFAULT)]); session_regenerate_id(true); $_SESSION['cliente_id']=(int)$pdo->lastInsertId(); $_SESSION['cliente_nombre']=$n; header('Location: cliente/index.php?bienvenida=1'); exit; }
 catch(PDOException $x) { if($x->getCode()==='23000') $error='Ese correo ya tiene una cuenta registrada.'; else {error_log($x->getMessage());$error='No se pudo crear la cuenta. Inténtalo más tarde.';} } } }
?>
